let pendingDeleteItem=null,pendingDeleteChoice=null;
function closeDeleteDialog(){const modal=$('#deleteBackdrop');modal.classList.remove('open');pendingDeleteItem=null;pendingDeleteChoice=null}
function openDeleteDialog(item){pendingDeleteItem=item;pendingDeleteChoice=null;renderDeleteDialog();$('#deleteBackdrop').classList.add('open');$('#deleteCancel').focus()}
function renderDeleteDialog(){const item=pendingDeleteItem;if(!item)return;const isSeries=!!item.seriesId&&item.repeat&&item.repeat!=='none';const label=item.category==='Money'&&item.amount!=null?'bill':'reminder';$('#deleteTitle').textContent=isSeries?'Delete recurring '+label:'Delete '+label;$('#deleteSubtitle').textContent=item.title;const content=$('#deleteDialogContent');if(!isSeries){content.innerHTML='<p class="delete-copy">This will permanently delete this '+label+'.</p><div class="delete-actions"><button class="secondary" id="deleteCancel" type="button">Cancel</button><button class="delete-danger" id="deleteConfirm" type="button">Delete '+label+'</button></div>';return}if(!pendingDeleteChoice){content.innerHTML='<p class="delete-copy">Choose what you want to remove. You can’t undo this action.</p><div class="delete-options"><button class="delete-option" type="button" data-delete-choice="1"><span class="delete-option-icon">×</span><span><strong>Only this occurrence</strong><small>Keep the rest of the series.</small></span><span class="delete-chevron">›</span></button><button class="delete-option" type="button" data-delete-choice="2"><span class="delete-option-icon">→</span><span><strong>This and future occurrences</strong><small>Keep previous entries as history and stop the series.</small></span><span class="delete-chevron">›</span></button><button class="delete-option delete-option-danger" type="button" data-delete-choice="3"><span class="delete-option-icon">×</span><span><strong>Entire series</strong><small>Remove all occurrences, including future ones.</small></span><span class="delete-chevron">›</span></button></div><div class="delete-actions"><button class="secondary" id="deleteCancel" type="button">Cancel</button></div>';return}const seriesItems=data.filter(x=>x.seriesId===item.seriesId);let targets,prior=[];if(pendingDeleteChoice==='3')targets=seriesItems;else if(pendingDeleteChoice==='2'){targets=seriesItems.filter(x=>Number.isInteger(x.seriesIndex)&&x.seriesIndex>=item.seriesIndex);prior=seriesItems.filter(x=>Number.isInteger(x.seriesIndex)&&x.seriesIndex<item.seriesIndex)}else targets=[item];const desc=pendingDeleteChoice==='3'?'the entire series':pendingDeleteChoice==='2'?'this occurrence and all future occurrences':'this occurrence';content.innerHTML='<p class="delete-copy">You’re about to delete <strong>'+esc(desc)+'</strong> for <strong>'+esc(item.title)+'</strong>.</p><div class="delete-count"><strong>'+targets.length+'</strong><span>occurrence'+(targets.length===1?'':'s')+' will be deleted</span></div>'+(prior.length?'<p class="delete-note">Previous entries will be kept as history, and recurrence will be stopped.</p>':'')+'<div class="delete-actions"><button class="secondary" id="deleteBack" type="button">Back</button><button class="delete-danger" id="deleteConfirm" type="button">Delete '+(pendingDeleteChoice==='3'?'series':pendingDeleteChoice==='2'?'future entries':'occurrence')+'</button></div>'}
async function performDelete(){const item=pendingDeleteItem;if(!item)return;const isSeries=!!item.seriesId&&item.repeat&&item.repeat!=='none';const choice=pendingDeleteChoice||'1';const seriesItems=isSeries?data.filter(x=>x.seriesId===item.seriesId):[item];let targets,prior=[];if(choice==='3')targets=seriesItems;else if(choice==='2'){targets=seriesItems.filter(x=>Number.isInteger(x.seriesIndex)&&x.seriesIndex>=item.seriesIndex);prior=seriesItems.filter(x=>Number.isInteger(x.seriesIndex)&&x.seriesIndex<item.seriesIndex)}else targets=[item];const label=item.category==='Money'&&item.amount!=null?'bill':'reminder';try{let detached=[];if(prior.length){detached=prior.map(x=>{const {seriesId,seriesStart,seriesIndex,...rest}=x;return {...rest,repeat:'none'}});await sync.save(detached)}await sync.removeMany(targets.map(x=>x.id));const targetIds=new Set(targets.map(x=>x.id));const detachedById=new Map(detached.map(x=>[x.id,x]));data=data.filter(x=>!targetIds.has(x.id)).map(x=>detachedById.get(x.id)||x);closeDeleteDialog();render();toast('Deleted '+(choice==='3'?'the series':choice==='2'?'future occurrences':'this occurrence')+'.')}catch(error){alert('Could not fully delete this '+label+': '+(error.message||'Please try again. Refresh Orbit to check the saved state.'))}}
$('#deleteBackdrop').addEventListener('click',e=>{if(e.target===$('#deleteBackdrop'))closeDeleteDialog()});$('#deleteClose').onclick=closeDeleteDialog;
$('#deleteDialogContent').addEventListener('click',e=>{const option=e.target.closest('[data-delete-choice]');if(option){pendingDeleteChoice=option.dataset.deleteChoice;renderDeleteDialog();$('#deleteConfirm')?.focus();return}if(e.target.closest('#deleteCancel')){closeDeleteDialog();return}if(e.target.closest('#deleteBack')){pendingDeleteChoice=null;renderDeleteDialog();return}if(e.target.closest('#deleteConfirm'))performDelete()});
document.addEventListener('click',async e=>{const done=e.target.closest('[data-done]');if(done){const id=done.dataset.done,item=data.find(x=>x.id===id);if(!item)return;if(!item.done&&item.repeat&&item.repeat!=='none'){if(!item.seriesId){item.seriesId=crypto.randomUUID();item.seriesStart=item.date;item.seriesIndex=0}const seriesItems=data.filter(x=>x.seriesId===item.seriesId),maxIndex=Math.max(item.seriesIndex||0,...seriesItems.map(x=>Number.isInteger(x.seriesIndex)?x.seriesIndex:0));if(maxIndex===(item.seriesIndex||0)){const nextIndex=maxIndex+1;data.push(...makeSeriesOccurrences(item,nextIndex,nextIndex))}}item.done=!item.done;try{await save()}catch{return}render();return}const paid=e.target.closest('[data-paid]');if(paid){const item=data.find(x=>x.id===paid.dataset.paid);if(item){item.paid=!item.paid;try{await save()}catch{return}render()}return}const del=e.target.closest('[data-delete]');if(del){const item=data.find(x=>x.id===del.dataset.delete);if(item)openDeleteDialog(item);return}const row=e.target.closest('.item');if(row?.dataset.edit&&!e.target.closest('button')){const item=data.find(x=>x.id===row.dataset.edit);if(item)openModal(item);return}if(row&&row.querySelector('[data-delete]')){const id=row.querySelector('[data-delete]').dataset.delete;const item=data.find(x=>x.id===id);if(item)openModal(item)}});document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.item[data-edit]')){e.preventDefault();const item=data.find(x=>x.id===e.target.dataset.edit);if(item)openModal(item)}});
